CREATE TABLE building_slot (id INTEGER PRIMARY KEY AUTOINCREMENT, town_id INTEGER NOT NULL REFERENCES town(id), position INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('TOWN_HALL','LAND','WALL','COAST')), required_town_hall_level INTEGER NOT NULL, building_type TEXT, building_level INTEGER, UNIQUE (town_id, position), CHECK ((building_type IS NULL) = (building_level IS NULL)));
